layer.css:
@import url("https://fonts.googleapis.com/css2?family=Noto+Sans+KR:wght@400;700&display=swap");
@import url("https://fonts.googleapis.com/css2?family=Fira+Code&display=swap");
@import url("https://fonts.googleapis.com/css2?family=Nanum+Gothic+Coding:wght@400;700&display=swap");
[data-ryt="pitch"] { color: var(--ryt-text); background-color: rgb(242, 242, 242); border-left: 4px solid rgb(250, 139, 132); border-radius: 4px; font-family: "Franklin Gothic Medium", "Arial Narrow", Arial, sans-serif; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.8; letter-spacing: 0.5px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 4px; padding-right: 24px; padding-bottom: 4px; padding-left: 24px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: -0.3px; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-text); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: -0.3px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="hero"] h1 { color: #8c8c8c; font-family: var(--ryt-font-heading); font-size: 15.2px; font-weight: 400; font-style: normal; line-height: 1.75; letter-spacing: -0.3px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: #8c8c8c; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 15.2px; font-weight: 400; font-style: normal; line-height: 1.75; letter-spacing: -0.3px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
